import{_ as e,o as r,c as t,a3 as i}from"./chunks/framework.Dj4Lt7vj.js";const u=JSON.parse('{"title":"效果与使用建议","description":"","frontmatter":{"title":"效果与使用建议"},"headers":[],"relativePath":"faq/effect.md","filePath":"faq/effect.md","lastUpdated":1787949005000}'),o={name:"faq/effect.md"};function l(n,a,s,c,h,d){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="效果与使用建议" tabindex="-1">效果与使用建议 <a class="header-anchor" href="#效果与使用建议" aria-label="Permalink to &quot;效果与使用建议&quot;">​</a></h1><p>关于「用了之后效果怎么样」的问题，和让效果更好的做法。</p><h2 id="ai-能替代人工客服吗" tabindex="-1">AI 能替代人工客服吗？ <a class="header-anchor" href="#ai-能替代人工客服吗" aria-label="Permalink to &quot;AI 能替代人工客服吗？&quot;">​</a></h2><p>合理的预期是：AI 接住大部分重复咨询，人工处理真正需要人的部分。</p><ul><li>AI 擅长：发货时效、退换政策、商品参数、活动规则这类有标准答案的问题。</li><li>人工保留：投诉纠纷、复杂售后、议价决策、需要查订单系统的操作。</li></ul><p>配置好<a href="/aicare-docs/solution/transfer">转人工</a>，让两边各干各的。</p><h2 id="上线第一周该做什么" tabindex="-1">上线第一周该做什么？ <a class="header-anchor" href="#上线第一周该做什么" aria-label="Permalink to &quot;上线第一周该做什么？&quot;">​</a></h2><ol><li><strong>第 1–2 天</strong>：只开一个店铺试跑，每天翻<a href="/aicare-docs/workspace/records">聊天记录</a>看 AI 的实际回复。</li><li><strong>第 3–4 天</strong>：把发现的答错、答偏问题按<a href="/aicare-docs/faq/accuracy">排查方法</a>修掉，补知识库。</li><li><strong>之后</strong>：逐步放量到其他店铺，建立每周看消耗、每周补知识缺口的习惯。</li></ol><p>冷启动阶段多花的功夫，后面都会省回来。</p><h2 id="顾客能看出来是-ai-吗" tabindex="-1">顾客能看出来是 AI 吗？ <a class="header-anchor" href="#顾客能看出来是-ai-吗" aria-label="Permalink to &quot;顾客能看出来是 AI 吗？&quot;">​</a></h2><p>回复质量取决于你的配置：知识库越贴合店铺、话术要求越具体，回复越自然。<a href="/aicare-docs/solution/general">通用配置</a>里适当调大消息间隔，也会更像人工节奏。</p><h2 id="怎么衡量效果" tabindex="-1">怎么衡量效果？ <a class="header-anchor" href="#怎么衡量效果" aria-label="Permalink to &quot;怎么衡量效果？&quot;">​</a></h2><p>工作台里三处数据：</p><ul><li><strong>仪表盘</strong>：接待量等核心数据的整体走势。</li><li><strong>数据分析</strong>:工具调用次数、转接对象占比、转接成功率。</li><li><strong>聊天记录 → 待跟进</strong>：AI 没接住的会话都在这里，数量下降说明配置在变好。</li></ul><h2 id="夜里没人值守-咨询会丢吗" tabindex="-1">夜里没人值守，咨询会丢吗？ <a class="header-anchor" href="#夜里没人值守-咨询会丢吗" aria-label="Permalink to &quot;夜里没人值守，咨询会丢吗？&quot;">​</a></h2><p>开启<a href="/aicare-docs/solution/general#服务策略">夜间服务模式</a>：指定时段内本该转人工的会话改为发夜间话术（比如「已留言，明早优先处理」），第二天从待跟进列表逐个回访。配合<a href="/aicare-docs/client/notify">微信通知</a>，紧急情况也不会漏。</p><h2 id="多店铺怎么配置最省事" tabindex="-1">多店铺怎么配置最省事？ <a class="header-anchor" href="#多店铺怎么配置最省事" aria-label="Permalink to &quot;多店铺怎么配置最省事？&quot;">​</a></h2><ul><li>同类目、同话术的店铺<strong>共用一个 AI 方案</strong>，改一处全部生效。</li><li>售后政策等全店通用的资料放一个通用知识库，绑给所有方案。</li><li>差异大的店铺再单独建方案。</li></ul><h2 id="什么时候该升级套餐" tabindex="-1">什么时候该升级套餐？ <a class="header-anchor" href="#什么时候该升级套餐" aria-label="Permalink to &quot;什么时候该升级套餐？&quot;">​</a></h2><p>出现这几个信号时考虑升档：套餐点数经常在周期结束前用完；客服账号接入位达到上限；需要情景分流、表格、商品智能整理等按套餐开放的能力。具体档位和权益以「账单」页为准，见<a href="/aicare-docs/start/plan">套餐与开通</a>。</p>',20)])])}const p=e(o,[["render",l]]);export{u as __pageData,p as default};
